style.css:
@-moz-document domain("tusitio.com") {
:root {
        /* Colores de fondo principales */
        --white: #1e1e1e;
        --light: #2d2d2d;
        --gray: #b0b0b0;
        --gray-dark: #f8f9fa;

        /* Colores de texto */
        --dark: #e0e0e0;
        --primary: #4dabf7; /* Un azul más claro para que resalte en fondo oscuro */
        --secondary: #495057;

        /* Ajuste de colores de actividades para modo oscuro */
        --activityadministration: #7a7fff;
        --activityassessment: #f089b6;
        --activitycollaboration: #ff8a7a;
        --activitycommunication: #32c794;
        --activitycontent: #60b2f0;
        --activityinterface: #b899ff;

        /* Otros ajustes */
        --blue: #339af0;
        --info: #3bc9db;
    }

    /* Aplicación global al cuerpo y HTML */
    body, html {
        background-color: #121212 !important;
        color: #e0e0e0 !important;
    }

    /* Ajuste para elementos comunes que suelen quedarse blancos */
    .card, .modal-content, .dropdown-menu, .nav-tabs .nav-link.active {
        background-color: #1e1e1e !important;
        border-color: #333 !important;
        color: #e0e0e0 !important;
    }

    /* Ajuste de enlaces */
    a {
        color: #74c0fc !important;
    }

    a:hover {
        color: #a5d8ff !important;
    }

    /* Inputs y formularios */
    input, select, textarea {
        background-color: #2b2b2b !important;
        color: #ffffff !important;
        border: 1px solid #444 !important;
    }

    /* Invertir imágenes o logos blancos si es necesario (opcional) */
    /* img.logo { filter: invert(1) hue-rotate(180deg); } */

    /* Scrollbar para navegadores modernos */
    ::-webkit-scrollbar {
        width: 12px;
    }
    ::-webkit-scrollbar-track {
        background: #1e1e1e;
    }
    ::-webkit-scrollbar-thumb {
        background: #444;
        border-radius: 6px;
    }
    ::-webkit-scrollbar-thumb:hover {
        background: #555;
    }
}
